script:
export const meta = {
  name: 'locate-ip-marks',
  description: 'Locate every real-world brand mark in 64 benchmark images as precise bounding boxes for masked inpainting',
  phases: [
    { title: 'Locate', detail: 'one agent per task: tight pixel boxes + mark type for every leak' },
    { title: 'Audit', detail: 'independently re-check each box actually contains the mark' },
  ],
}

const SCHEMA = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    images: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          filename: { type: 'string' },
          image_size: { type: 'array', items: { type: 'number' } },
          boxes: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                pixel_box: { type: 'array', items: { type: 'number' } },
                box: { type: 'array', items: { type: 'number' } },
                what: { type: 'string' },
                mark_type: { type: 'string' },
                confirmed: { type: 'string' },
              },
              required: ['pixel_box', 'box', 'what', 'mark_type'],
            },
          },
          not_found: { type: 'array', items: { type: 'string' } },
          extra_marks_found: { type: 'array', items: { type: 'string' } },
        },
        required: ['filename', 'image_size', 'boxes'],
      },
    },
  },
  required: ['task_id', 'images'],
}

const AUDIT = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    checked: { type: 'number' },
    bad_boxes: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          filename: { type: 'string' },
          pixel_box: { type: 'array', items: { type: 'number' } },
          problem: { type: 'string' },
          corrected_pixel_box: { type: 'array', items: { type: 'number' } },
        },
        required: ['filename', 'pixel_box', 'problem'],
      },
    },
    verdict: { type: 'string' },
  },
  required: ['task_id', 'checked', 'bad_boxes', 'verdict'],
}

const V3 = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads/input_assets_v3'
const OUT = '/private/tmp/claude-501/-Users-dhiren-Downloads-Deccan/aa9e6dfc-7579-493e-a3a8-45be309ed406/scratchpad/ipsweep'

function locatePrompt(t) {
  const list = t.images.map(im =>
    `  FILE: ${im.filename}\n    marks reported by the sweep:\n${im.marks.map(m => '      - ' + m).join('\n')}`
  ).join('\n')
  return `You are locating real-world brand markings precisely so they can be masked out by inpainting. COORDINATE ACCURACY IS THE ENTIRE JOB. A box that is too big destroys good pixels; a box that is too small leaves the trademark visible.

TASK ${t.task_id}. Images live in ${V3}/${t.task_id}/assets/

${list}

FOR EVERY image above, find EVERY instance of every reported mark and give a TIGHT bounding box per instance.

METHOD, follow it exactly:
- Open each image at FULL resolution with PIL. Print its exact pixel dimensions FIRST and use those dimensions for the normalised coordinates.
- Never estimate coordinates from a thumbnail. Crop and magnify (8x to 16x, nearest-neighbour) to confirm you are looking at the real mark.
- Measure extents from pixel data: thresholded row/column profiles, or direct inspection of magnified crops.
- VERIFY each box by re-cropping exactly the box you propose and confirming the mark is fully inside with only a few percent margin.
- A box must be TIGHT around the mark itself, not around the object carrying it. A logo on a shirt gets the logo, not the shirt. A wordmark on a label gets that line of text, not the whole label.
- If a reported mark is NOT actually there or you cannot resolve it, list it in not_found. NEVER invent a box. A previous agent in this project confidently reported a mark that did not exist, so under-reporting is far better than guessing.
- While you are in the image, also look for UNDECLARED real marks the sweep missed: apparel logos, background signage, book spines, vehicle badges, screen/OS chrome. Real examples already missed in this corpus: Boar's Head deli signage, Nike, The North Face, Under Armour. Add any you find as boxes too, and note them in extra_marks_found.

mark_type MUST be one of these exact strings, because it selects the repair instruction:
  "badge_on_object"  a rigid emblem/badge on a hard surface (car badge, appliance badge) -> repair by continuing the surrounding surface
  "logo_on_fabric"   a printed/embroidered logo on clothing or soft goods -> repair by continuing the fabric weave, fold and shading
  "text_line"        a line of printed text/wordmark on a label, sign, spine or packaging -> repair by continuing the printed surface, leaving it blank
  "number_plate"     a vehicle registration plate -> repair by KEEPING the plate but making it blank and unlettered, NOT by deleting the plate
  "ui_chrome"        operating-system or browser furniture (taskbar, tab strip, omnibox) -> usually a wide strip, box it exactly
  "other"            anything that does not fit; explain in what

Also set:
  what          a short precise description of THIS one mark
  pixel_box     [x0,y0,x1,y1] integers in pixels
  box           the same box NORMALISED to 0-1 as floats [x0/W, y0/H, x1/W, y1/H]
  confirmed     one sentence on how you verified it

Return the structured object. Also write the same JSON to ${OUT}/boxes/${t.task_id}.json`
}

function auditPrompt(t, loc) {
  return `You are auditing bounding boxes another agent produced for task ${t.task_id}, before they are used to mask and repaint parts of these images. A wrong box either leaves a live trademark visible or destroys good pixels, so check them adversarially.

Images: ${V3}/${t.task_id}/assets/
Boxes to audit (JSON): ${JSON.stringify(loc).slice(0, 12000)}

For EVERY box: crop exactly that pixel_box out of the image at full resolution and look at it.
- Does the crop actually contain the described mark, fully and completely? If any part of the mark falls outside the box, that is a bad box: report it with a corrected_pixel_box.
- Is the box excessively large, covering much more than the mark plus a small margin? Report it with a tighter corrected_pixel_box.
- Does the normalised box agree with the pixel box given the real image dimensions? Recompute and check.
- Is mark_type appropriate, especially: is anything labelled something other than "number_plate" actually a vehicle plate, or vice versa?

Report ONLY genuine problems in bad_boxes. If the boxes are good, return an empty bad_boxes array and say so in verdict. Do not manufacture issues to look thorough.`
}

phase('Locate')
log(`locating marks across ${args.length} tasks`)

const results = await pipeline(
  args,
  (t) => agent(locatePrompt(t), { label: `locate:${t.task_id}`, phase: 'Locate', schema: SCHEMA }),
  (loc, t) => {
    if (!loc) return null
    return agent(auditPrompt(t, loc), { label: `audit:${t.task_id}`, phase: 'Audit', schema: AUDIT })
      .then(aud => ({ task_id: t.task_id, located: loc, audit: aud }))
  }
)

const good = results.filter(Boolean)
const totalBoxes = good.reduce((n, r) => n + (r.located.images || []).reduce((m, i) => m + (i.boxes || []).length, 0), 0)
const badBoxes = good.reduce((n, r) => n + ((r.audit && r.audit.bad_boxes) ? r.audit.bad_boxes.length : 0), 0)
const extras = good.flatMap(r => (r.located.images || []).flatMap(i => (i.extra_marks_found || []).map(e => `${r.task_id}/${i.filename}: ${e}`)))
const notFound = good.flatMap(r => (r.located.images || []).flatMap(i => (i.not_found || []).map(e => `${r.task_id}/${i.filename}: ${e}`)))

log(`located ${totalBoxes} boxes; audit flagged ${badBoxes}; ${extras.length} undeclared marks found`)
if (good.length < args.length) log(`WARNING: ${args.length - good.length} task(s) returned nothing and were dropped`)

return { tasks_done: good.length, tasks_requested: args.length, total_boxes: totalBoxes, bad_boxes: badBoxes, undeclared_marks: extras, not_found: notFound, results: good }
